+package com.example.contact;
+
+import java.time.Instant;
+import java.util.List;
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.Component;
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final Pattern EMAIL = Pattern.compile("[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}");
+
+    private final MessageStore store;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send", e -> submit());
+
+    private final Grid<SentMessage> grid = new Grid<>(SentMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+
+        for (Component field : List.<Component>of(name, email, phone, message)) {
+            Shortcuts.addShortcutListener(field, this::submitFromKeyboard, Key.ENTER);
+        }
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        grid.addColumn(SentMessage::name).setHeader("Name");
+        grid.addColumn(SentMessage::email).setHeader("Email");
+        grid.addColumn(SentMessage::phone).setHeader("Phone");
+        grid.addColumn(SentMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(store.findAll());
+
+        configureLeaveDialog();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), name, email, phone, message,
+                new HorizontalLayout(send), grid, leaveDialog);
+    }
+
+    private void configureLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("The contact form has unsent input. Leaving will lose it."));
+        leaveDialog.setCloseOnEsc(false);
+        leaveDialog.setCloseOnOutsideClick(false);
+
+        var keepEditing = new Button("Keep editing", e -> keepEditing());
+        var discard = new Button("Discard", e -> discard());
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private void keepEditing() {
+        var navigation = pendingNavigation;
+        pendingNavigation = null;
+        leaveDialog.close();
+        if (navigation != null) {
+            navigation.cancel();
+        }
+    }
+
+    private void discard() {
+        var navigation = pendingNavigation;
+        pendingNavigation = null;
+        leaveDialog.close();
+        clearFields();
+        if (navigation != null) {
+            navigation.proceed();
+        }
+    }
+
+    private void submitFromKeyboard() {
+        if (send.isEnabled()) {
+            submit();
+        }
+    }
+
+    private void submit() {
+        var sender = name.getValue().trim();
+        var address = email.getValue().trim();
+        var phoneNumber = phone.getValue().trim();
+        var text = message.getValue().trim();
+
+        if (!validate(sender, address, phoneNumber, text)) {
+            return;
+        }
+
+        store.add(new SentMessage(sender, address, phoneNumber, text, Instant.now()));
+        grid.setItems(store.findAll());
+        Notification.show("Message sent");
+
+        clearFields();
+        send.setEnabled(false);
+    }
+
+    private boolean validate(String sender, String address, String phoneNumber, String text) {
+        String nameError = sender.isEmpty() ? "Name is required" : null;
+
+        String emailError = null;
+        if (!address.isEmpty() && !EMAIL.matcher(address).matches()) {
+            emailError = "Enter a valid e-mail address";
+        } else if (address.isEmpty() && phoneNumber.isEmpty()) {
+            emailError = "Give an e-mail address or a phone number";
+        }
+
+        String messageError = null;
+        if (text.isEmpty()) {
+            messageError = "Message is required";
+        } else if (text.length() > MAX_MESSAGE_LENGTH) {
+            messageError = "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+
+        mark(name, nameError);
+        mark(email, emailError);
+        mark(message, messageError);
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private static void mark(HasValidation field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(error != null);
+    }
+
+    private boolean hasInput() {
+        return hasText(name.getValue()) || hasText(email.getValue())
+                || hasText(phone.getValue()) || hasText(message.getValue());
+    }
+
+    private static boolean hasText(String value) {
+        return value != null && !value.isEmpty();
+    }
+
+    private void clearFields() {
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+    }
+
+}
