+package com.example.contact;
+
+import java.util.ArrayDeque;
+import java.util.Deque;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps every message sent through the contact form for as long as the application runs.
+ */
+@Service
+public class MessageStore {
+
+    private final Deque<SentMessage> messages = new ArrayDeque<>();
+
+    public synchronized void add(SentMessage message) {
+        messages.addFirst(message);
+    }
+
+    /**
+     * @return all sent messages, newest first
+     */
+    public synchronized List<SentMessage> findAll() {
+        return List.copyOf(messages);
+    }
+
+}
