+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.assertions.PlaywrightAssertions;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
+
+@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
+class ContactBrowserTest {
+
+    @Value("${local.server.port}")
+    private int port;
+
+    private static Playwright playwright;
+    private static Browser browser;
+    private Page page;
+
+    @BeforeAll
+    static void startBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void sendsAMessageAndShowsItInTheList() {
+        page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/contact");
+
+        Locator heading = page.locator("h1", new Page.LocatorOptions().setHasText("Contact"));
+        PlaywrightAssertions.assertThat(heading).isVisible();
+
+        Locator send = page.getByRole(AriaRole.BUTTON,
+                new Page.GetByRoleOptions().setName("Send"));
+        send.click();
+        PlaywrightAssertions.assertThat(page.getByText("Name is required")).isVisible();
+
+        page.getByRole(AriaRole.TEXTBOX, new Page.GetByRoleOptions().setName("Name").setExact(true)).fill("Browser Ann");
+        page.getByRole(AriaRole.TEXTBOX, new Page.GetByRoleOptions().setName("Phone").setExact(true)).fill("+358 40 123");
+        page.getByRole(AriaRole.TEXTBOX, new Page.GetByRoleOptions().setName("Message").setExact(true)).fill("Hello from a browser");
+        page.getByRole(AriaRole.TEXTBOX, new Page.GetByRoleOptions().setName("Message").setExact(true)).press("Enter");
+
+        PlaywrightAssertions.assertThat(page.getByText("Message sent")).isVisible();
+        PlaywrightAssertions.assertThat(page.locator("vaadin-grid")
+                .getByText("Hello from a browser")).isVisible();
+        assertEquals("", page.getByRole(AriaRole.TEXTBOX, new Page.GetByRoleOptions().setName("Name").setExact(true)).inputValue());
+        page.close();
+    }
+
+    @Test
+    void aboutLinkAsksBeforeDiscardingTypedInput() {
+        page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/contact");
+
+        page.getByRole(AriaRole.TEXTBOX, new Page.GetByRoleOptions().setName("Phone").setExact(true)).fill("+358 40 123");
+        page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName("About")).click();
+
+        Locator keepEditing = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing"));
+        PlaywrightAssertions.assertThat(keepEditing).isVisible();
+        keepEditing.click();
+        PlaywrightAssertions.assertThat(keepEditing).not().isVisible();
+        assertEquals("+358 40 123", page.getByRole(AriaRole.TEXTBOX, new Page.GetByRoleOptions().setName("Phone").setExact(true)).inputValue());
+
+        page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName("About")).click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1", new Page.LocatorOptions().setHasText("About")))
+                .isVisible();
+        page.close();
+    }
+
+}
