+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+// The message store is shared by the whole application context, so every
+// assertion on the list is relative to what was there when the view opened.
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+    private int listedBefore;
+
+    @BeforeEach
+    void open() {
+        navigate(ContactView.class);
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+        listedBefore = listed();
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue, String messageValue) {
+        name.setValue(nameValue);
+        email.setValue(emailValue);
+        phone.setValue(phoneValue);
+        message.setValue(messageValue);
+    }
+
+    private int listed() {
+        return grid().getListDataView().getItemCount();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<SentMessage> grid() {
+        return $(Grid.class).single();
+    }
+
+    private boolean notified(String text) {
+        return $(Notification.class).all().stream()
+                .anyMatch(n -> n.getElement().getProperty("text", "").contains(text));
+    }
+
+    @Test
+    void headingAndFieldsArePresentAndEmptyWithSendEnabled() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void aboutLinkNavigatesToAboutView() {
+        navigate("about", AboutView.class);
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void blankFormMarksAllRequiredRules() {
+        send.click();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertEquals(listedBefore, listed());
+        assertFalse(notified("Message sent"));
+    }
+
+    @Test
+    void invalidEmailIsRejectedEvenWithPhone() {
+        fill("Ann", "not-an-address", "123", "Hello");
+        send.click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertFalse(name.isInvalid());
+        assertFalse(message.isInvalid());
+        assertEquals("Ann", name.getValue());
+        assertEquals("not-an-address", email.getValue());
+        assertEquals(listedBefore, listed());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        fill("Ann", "ann@example.com", "", "x".repeat(501));
+        send.click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(501, message.getValue().length());
+        assertEquals(listedBefore, listed());
+    }
+
+    @Test
+    void messageOf500CharactersIsAccepted() {
+        fill("Ann", "ann@example.com", "", "x".repeat(500));
+        send.click();
+
+        assertFalse(message.isInvalid());
+        assertEquals("", message.getValue());
+        assertEquals(listedBefore + 1, listed());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnough() {
+        fill("Ann", "", "+358 40 123", "Call me");
+        send.click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(listedBefore + 1, listed());
+    }
+
+    @Test
+    void emailAloneIsEnough() {
+        fill("Ann", "ann@example.com", "", "Write to me");
+        send.click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(listedBefore + 1, listed());
+    }
+
+    @Test
+    void validSendNotifiesListsClearsAndDisablesSend() {
+        fill("Ann", "ann@example.com", "", "Hello there");
+        send.click();
+
+        assertTrue(notified("Message sent"));
+        SentMessage first = grid().getListDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Ann", first.name());
+        assertEquals("Hello there", first.message());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+    }
+
+    @Test
+    void editingAfterSendReenablesSend() {
+        fill("Ann", "ann@example.com", "", "Hello");
+        send.click();
+        assertFalse(send.isEnabled());
+
+        name.setValue("B");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void newestMessageIsFirstAndSurvivesRevisiting() {
+        fill("First", "", "123", "one");
+        send.click();
+        fill("Second", "", "456", "two");
+        send.click();
+
+        navigate("about", AboutView.class);
+        navigate(ContactView.class);
+        assertEquals(listedBefore + 2, listed());
+        assertEquals("Second", grid().getListDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        fill("Ann", "", "123", "Via enter");
+        name.focus();
+        fireShortcut(Key.ENTER);
+
+        assertEquals(listedBefore + 1, listed());
+        assertEquals("", message.getValue());
+    }
+
+    @Test
+    void leavingWithInputAsksFirstAndKeepEditingStays() {
+        fill("Ann", "", "123", "draft");
+        UI.getCurrent().navigate("about");
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        $(Button.class).withText("Keep editing").single().click();
+        assertFalse(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("draft", message.getValue());
+        assertEquals("Ann", name.getValue());
+    }
+
+    @Test
+    void discardGoesToAboutView() {
+        fill("Ann", "", "123", "draft");
+        UI.getCurrent().navigate("about");
+        $(Button.class).withText("Discard").single().click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAskAnything() {
+        navigate("about", AboutView.class);
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+}
